  `venueId` NUMBER,
  `venueName` TEXT,
  PRIMARY KEY (`venueId`)
);

CREATE TABLE `author` (
  `authorId` NUMBER,
  `authorName` TEXT,
  PRIMARY KEY (`authorId`)
);

CREATE TABLE `dataset` (
  `datasetId` NUMBER,
  `datasetName` TEXT,
  PRIMARY KEY (`datasetId`)
);

CREATE TABLE `journal` (
  `journalId` NUMBER,
  `journalName` TEXT,
  PRIMARY KEY (`journalId`)
);

CREATE TABLE `keyphrase` (
  `keyphraseId` NUMBER,
  `keyphraseName` TEXT,
  PRIMARY KEY (`keyphraseId`)
);

CREATE TABLE `paper` (
  `paperId` NUMBER,
  `title` TEXT,
  `venueId` NUMBER REFERENCES `venue`(`venueId`),
  `year` NUMBER,
  `numCiting` NUMBER,
  `numCitedBy` NUMBER,
  `journalId` NUMBER REFERENCES `journal`(`journalId`),
  PRIMARY KEY (`paperId`)
);

CREATE TABLE `cite` (
  `citingPaperId` NUMBER REFERENCES `paper`(`paperId`),
  `citedPaperId` NUMBER REFERENCES `paper`(`paperId`),
  PRIMARY KEY (`citingPaperId`)
);

CREATE TABLE `paperDataset` (
  `paperId` NUMBER,
  `datasetId` NUMBER,
  PRIMARY KEY (`datasetId`)
);

CREATE TABLE `paperKeyphrase` (
  `paperId` NUMBER REFERENCES `paper`(`paperId`),
  `keyphraseId` NUMBER REFERENCES `keyphrase`(`keyphraseId`),
  PRIMARY KEY (`keyphraseId`)
);

CREATE TABLE `writes` (
  `paperId` NUMBER REFERENCES `paper`(`paperId`),
  `authorId` NUMBER REFERENCES `author`(`authorId`),
  PRIMARY KEY (`paperId`)
);

